import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, consider an {rows} by {cols} rectangular grid G whose cells are assigned arbitrary real numbers (you may choose the values adversarially to maximize the count). For a fixed nonnegative integer {radius} and a fixed integer {min_side} with 1 <= {min_side} <= min({rows},{cols}), we say a rectangular sub-grid S is radius-outstanding if: (i) every cell of S has a value strictly greater than every cell outside S whose Chebyshev distance to S is at most {radius} (that is, outside cells within {radius} king-steps from S), and (ii) the {radius}-dilation of S (the set of all cells within Chebyshev distance at most {radius} from S) lies entirely inside G. The entire grid G is also considered radius-outstanding when it satisfies (ii). Among all possible assignments of real numbers to the cells of G, determine the maximum possible number of radius-outstanding sub-rectangles of G whose side lengths are both at least {min_side}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate rows, cols moderately large but safe.
# radius in [0, min(rows, cols)//3], min_side in [1, min(rows, cols)//2].
# Ensure nontrivial counts: effective interior after dilation must be >= min_side.
for _ in range(1000):
    rows = rng.randint(20, 120)
    cols = rng.randint(20, 150)
    rad_max = max(0, min(rows, cols)//3)
    radius = rng.randint(0, rad_max)
    min_side = rng.randint(1, max(1, min(rows, cols)//2))
    # Effective usable lengths after radius-dilation: R = rows - 2*radius, C = cols - 2*radius
    R = rows - 2*radius
    C = cols - 2*radius
    if R <= 0 or C <= 0:
        continue
    # Count intervals of length >= min_side in dimension with length L = R or C:
    # number of intervals of length >= s equals sum_{l=s..L} (L - l + 1) = L(L+1)/2 - (s-1)s/2
    def intervals_count(L, s):
        if L < s:
            return 0
        return L*(L+1)//2 - (s-1)*s//2
    ir = intervals_count(R, min_side)
    ic = intervals_count(C, min_side)
    total = ir * ic
    # Ensure it's nontrivial (at least a few hundred) and not too huge (safe for display):
    if total >= 200 and total <= 10**9:
        return {
            'rows': rows,
            'cols': cols,
            'radius': radius,
            'min_side': min_side
        }
# Fallback deterministic instance
rows, cols, radius, min_side = 60, 90, 10, 8
return {
    'rows': rows,
    'cols': cols,
    'radius': radius,
    'min_side': min_side
}

    def verifier(assign):
# Verify domain and compute the maximum number of radius-outstanding rectangles as described.
# Strategy: The dilation constraint (ii) forces valid rectangles to lie at least 'radius' away from each grid boundary.
# For a rectangle to be counted, both side lengths must be >= min_side.
# Among all assignments, one can realize all such rectangles simultaneously by assigning a strictly decreasing
# potential in Chebyshev layers measured from the admissible interior band; hence the maximum equals the count
# of such admissible rectangles determined purely combinatorially.
# We compute it as the product of the number of admissible intervals on rows and on cols.
rows = assign.get('rows')
cols = assign.get('cols')
radius = assign.get('radius')
min_side = assign.get('min_side')
# Basic validation
if not (isinstance(rows, int) and isinstance(cols, int) and isinstance(radius, int) and isinstance(min_side, int)):
    # invalid types
    return (False, None)
if rows <= 0 or cols <= 0 or radius < 0:
    return (False, None)
if min_side < 1 or min_side > min(rows, cols):
    return (False, None)
R = rows - 2*radius
C = cols - 2*radius
if R <= 0 or C <= 0:
    # No rectangle can have its radius-dilation entirely inside.
    return (True, 0)
if min_side > R or min_side > C:
    # Even the minimal side length not satisfied after erosion.
    return (True, 0)
def intervals_count(L, s):
    # number of contiguous intervals of [1..L] of length at least s
    return L*(L+1)//2 - (s-1)*s//2
ir = intervals_count(R, min_side)
ic = intervals_count(C, min_side)
answer = ir * ic
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

